148: 
149:         List<Profissional> profissionais = profissionalRepository.findAllById(profissionalIds);
150:         if (profissionais.size() != profissionalIds.size()) {
151:             throw new RecursoNaoEncontradoException("um ou mais profissionais informados nao existem");
152:         }
153: 
154:         boolean mesmaUnidade = profissionais.stream()
155:                 .allMatch(profissional -> profissional.getUnidade().getId().equals(unidadeId));
156:         if (!mesmaUnidade) {
