            <label>Tipo<select name="excecaoTipo" [(ngModel)]="excecaoTipo">
              <option value="FOLGA">Folga (dia inteiro)</option>
              <option value="JORNADA_ESPECIAL">Jornada especial</option>
            </select></label>
          </div>
